# Standard library
import uuid

# Third-party
from sqlalchemy import ForeignKey, Integer, Text, func
from sqlalchemy.orm import Mapped, mapped_column

# Local application
from app.core.base import Base, CreatorMixin, TimestampMixin


class ExplorerM2mRouteJourney(TimestampMixin, CreatorMixin, Base):
    __tablename__ = "explorer_m2m_route_journey"

    id: Mapped[uuid.UUID] = mapped_column(
        primary_key=True,
        server_default=func.gen_random_uuid(),
        comment=(
            "Primary key UUID, auto-generated by the "
            "database using gen_random_uuid()."
        ),
    )
    slot_position: Mapped[int] = mapped_column(
        Integer,
        nullable=False,
        comment=(
            "Zero-based ordering position of this "
            "route within the parent journey. "
            "Determines the sequence of daily stages."
        ),
    )
    route_id: Mapped[uuid.UUID] = mapped_column(
        ForeignKey("explorer_agg_route.id", ondelete="CASCADE"),
        nullable=False,
        comment=(
            "FK to explorer_agg_route with CASCADE "
            "delete. The planned route assigned to "
            "this day or stage of the journey."
        ),
    )
    journey_id: Mapped[uuid.UUID] = mapped_column(
        ForeignKey("explorer_agg_journey.id", ondelete="CASCADE"),
        nullable=False,
        comment=(
            "FK to explorer_agg_journey with CASCADE "
            "delete. The parent journey this route "
            "belongs to."
        ),
    )
    poi_id: Mapped[uuid.UUID | None] = mapped_column(
        ForeignKey("compendium_cat_poi.id"),
        comment=(
            "FK to compendium_cat_poi. Optional POI "
            "for this day's stage, such as an "
            "overnight hut or campsite."
        ),
    )
    day_name: Mapped[str] = mapped_column(
        Text,
        nullable=False,
        comment=(
            "Human-readable label for this day or "
            "stage, such as 'Day 1' or "
            "'Stage 3: Hut to Summit'. Required."
        ),
    )
    day_summary: Mapped[str | None] = mapped_column(
        Text,
        comment=(
            "Short summary of this day's route stage within the journey."
        ),
    )
    day_description: Mapped[str | None] = mapped_column(
        Text,
        comment=(
            "Detailed description of this day's route "
            "stage, including highlights and "
            "logistics."
        ),
    )
